    # Solid-color lines divide the grid into tiles.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def make_bands(size, separators):
        bands = []
        start = 0
        for p in separators:
            if start < p:
                bands.append(list(range(start, p)))
            start = p + 1
        if start < size:
            bands.append(list(range(start, size)))
        return bands

    row_bands = make_bands(h, sep_rows)
    col_bands = make_bands(w, sep_cols)
    if not row_bands or not col_bands:
        return [row[:] for row in grid]

    # The background is the most frequent color; use the tile with the most
    # non-background cells as the repeating pattern.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    source_rows, source_cols = max(
        ((rs, cs) for rs in row_bands for cs in col_bands),
        key=lambda tile: sum(
            grid[r][c] != background for r in tile[0] for c in tile[1]
        )
    )

    out = [row[:] for row in grid]
    for rs in row_bands:
        for cs in col_bands:
            for r in rs:
                for c in cs:
                    sr = source_rows[(r - rs[0]) % len(source_rows)]
                    sc = source_cols[(c - cs[0]) % len(source_cols)]
                    out[r][c] = grid[sr][sc]
    return out
